export RMAP_STATE_ROOT=/private/tmp/TRUST-MODULE-EDGES-1-rg RMAP_SOCKET_PATH=/private/tmp/TRUST-MODULE-EDGES-1-rg/d.sock RMAP_TRANSPORT=stdio RMAP_AUTO_ENRICH=off RMAP_AUTO_RETENTION=off && rust/target/release/rmap trust > /tmp/tme-trust.txt && grep -q 'Suspicious Modules (zero connectivity)' /tmp/tme-trust.txt && grep -Eq 'Import-graph: LOW \(alias resolution suspected; [0-9]+ unresolved imports\)' /tmp/tme-trust.txt && grep -Fq 'Change-impact: LOW (alias resolution suspected)' /tmp/tme-trust.txt && rust/target/release/rmap trust --json > /tmp/tme-trustj.json && python3 -c "import json,sys
d=json.load(open('/tmp/tme-trustj.json'))
ar=False; at=False
st=[(None,d)]
while st:
 key,o=st.pop()
 if isinstance(o,dict):
  r=o.get('reasons')
  if isinstance(r,list) and 'alias_resolution_suspicion' in r: ar=True
  if key=='alias_resolution_suspicion' and o.get('triggered') is True: at=True
  for k,v in o.items(): st.append((k,v))
 elif isinstance(o,list):
  for x in o: st.append((key,x))
sys.exit(0 if (ar and at) else 1)"
